export function recommend(filters, catalog=products){
 const {type,budget,purpose='study',brand='',ram=0,storage=0,os=''}=filters;
 if(!Number.isFinite(Number(budget))||Number(budget)<=0)return [];
 return catalog.filter(p=>p.type===type&&p.price<=Number(budget)&&(!ram||(p.ram!==null&&p.ram>=Number(ram)))&&(!storage||(p.storage!==null&&p.storage>=Number(storage)))&&(!os||p.os===os)&&(purpose!=='gaming'||p.fit.gaming>=75)&&(purpose!=='coding'||p.fit.coding>=60))
 .map(p=>({...p,score:p.fit[purpose]+(p.brand===brand?14:0)+Math.max(0,1-p.price/Number(budget))*7}))
 .sort((a,b)=>b.score-a.score||a.price-b.price);
}
